+// Example: How the edge worker validates sessions without database access
+// The edge worker has the public key baked in at build time
+
+import { validateSessionToken } from "./session-token.ts";
+
+// Called by edge worker when handling a request with an auth token
+export const authenticateRequest = (bearerToken: string): { userId: string } | null => {
+  // Extract token from "Bearer <token>" header
+  const token = bearerToken.replace(/^Bearer\s+/, "");
+
+  // Validate the signature and expiration—no database needed!
+  const session = validateSessionToken(token);
+  if (!session) return null;
+
+  return { userId: session.userId };
+};
+
+// Edge worker deployment:
+// 1. At build time, run: getPublicKeyForEdgeWorker() and bake it into the worker
+// 2. Edge worker calls validateSessionToken(token) for each request
+// 3. Signature verification is cryptographic and doesn't require network access
+// 4. Token expiration is checked locally; no database round-trip needed
