@@ -0,0 +1,67 @@
+import { createSign, createVerify, generateKeyPairSync } from "crypto";
+
+export interface SignedSession {
+  id: string;
+  userId: string;
+  issuedAt: number;
+  expiresAt: number;
+}
+
+// Key pair generated once and reused
+const { privateKey, publicKey } = generateKeyPairSync("rsa", {
+  modulusLength: 2048,
+  publicKeyEncoding: {
+    type: "spki",
+    format: "pem",
+  },
+  privateKeyEncoding: {
+    type: "pkcs8",
+    format: "pem",
+  },
+});
+
+export const getPublicKey = (): string => publicKey;
+
+export const issueSessionToken = (
+  sessionId: string,
+  userId: string,
+  ttlSeconds: number = 3600,
+): string => {
+  const now = Math.floor(Date.now() / 1000);
+  const session: SignedSession = {
+    id: sessionId,
+    userId,
+    issuedAt: now,
+    expiresAt: now + ttlSeconds,
+  };
+
+  const payload = JSON.stringify(session);
+  const sign = createSign("sha256");
+  sign.update(payload);
+  const signature = sign.sign(privateKey, "base64");
+
+  return `${Buffer.from(payload).toString("base64")}.${signature}`;
+};
+
+export const validateSessionToken = (token: string): SignedSession | null => {
+  try {
+    const [encodedPayload, signature] = token.split(".");
+    if (!encodedPayload || !signature) return null;
+
+    const payload = Buffer.from(encodedPayload, "base64").toString("utf-8");
+    const session: SignedSession = JSON.parse(payload);
+
+    const verify = createVerify("sha256");
+    verify.update(payload);
+    const isValid = verify.verify(publicKey, signature, "base64");
+
+    if (!isValid) return null;
+
+    const now = Math.floor(Date.now() / 1000);
+    if (now > session.expiresAt) return null;
+
+    return session;
+  } catch {
+    return null;
+  }
+};
